import { parseBoardCode } from './boardCode.ts';
import type { Board } from './boardCode.ts';

export const SELECTION = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export const MISMATCH_MS = 800;
export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;
export type Selection =
  | { readonly kind: typeof SELECTION.closed }
  | { readonly kind: typeof SELECTION.one; readonly index: number }
  | { readonly kind: typeof SELECTION.mismatch; readonly first: number;
      readonly second: number; readonly remainingMs: number };
export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  return board ? { board, matched: [], selection: { kind: SELECTION.closed },
    moves: 0, elapsedMs: 0, started: false } : null;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case SELECTION.closed: return false;
    case SELECTION.one: return state.selection.index === index;
    case SELECTION.mismatch:
      return state.selection.first === index || state.selection.second === index;
  }
}
EOF
cat > src/game/transitions.ts <<'EOF'
import { isWon, MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, SELECTION } from './model.ts';
import type { GameState } from './model.ts';

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length ||
      state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case SELECTION.closed:
      return { ...state, started: true, selection: { kind: SELECTION.one, index } };
    case SELECTION.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[first] === state.board.deck[index]) {
        return { ...state, moves, matched: [...state.matched, first, index],
          selection: { kind: SELECTION.closed } };
      }
      return { ...state, moves, selection: { kind: SELECTION.mismatch,
        first, second: index, remainingMs: MISMATCH_MS } };
    }
    case SELECTION.mismatch: return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) {
    return state;
  }
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection.kind === SELECTION.mismatch
    ? milliseconds >= state.selection.remainingMs
      ? { kind: SELECTION.closed }
      : { ...state.selection, remainingMs: state.selection.remainingMs - milliseconds }
    : state.selection;
  return { ...state, elapsedMs, selection };
}
EOF
