  if (!shape || !marker || !palette || !offset || !Number.isInteger(id) || id < 0 || id > 127) {
    throw new Error('Invalid face.');
  }
  const fill = id < 64 ? 'solid' : 'outline';
  return { shape, marker, color: palette.color, fill, x: 50 + offset[0], y: 50 + offset[1],
