      { atMs: 700, index: 11 }, { atMs: 800, index: 11 }], endMs: 1000 }))
      .toMatchObject({ moves: 1, elapsedMs: 500 });
    expect(replay({ actions: [], endMs: Number.MAX_SAFE_INTEGER }))
      .toMatchObject({ started: false, elapsedMs: 0 });
  });
