import { expect, test } from '@playwright/test';
import { card, DECK, freezeClock, loadBoard } from './helpers.ts';

test('complete keyboard and accessibility-tree journey with distinct announcements', async ({ page, browser }, info) => {
  const announcements: string[] = [];
  await page.exposeBinding('recordAnnouncement', (_source, text: unknown) => {
    if (typeof text === 'string') announcements.push(text);
  });
  await page.goto('/');
  expect(await page.evaluate(() => document.activeElement?.tagName)).toBe('BODY');
  await page.evaluate(() => {
    const region = document.querySelector('[aria-live]');
    const record: unknown = Reflect.get(window, 'recordAnnouncement');
    if (!region || typeof record !== 'function') throw new Error('Missing live region');
    new MutationObserver(() => { if (region.textContent) record(region.textContent); })
      .observe(region, { childList: true, characterData: true, subtree: true });
  });
  await loadBoard(page);
  await freezeClock(page);
  await page.clock.runFor(200);
  const evidence: string[] = [`Chromium ${browser.version()}; Playwright 1.64.1. No screen reader used.`];
  const capture = async (label: string) => evidence.push(`\n${label}\n${await page.locator('main').ariaSnapshot()}`);
  await capture('Hidden board, closed position names');
  expect(await page.locator('.board-grid svg').count()).toBe(0);
  expect(await page.locator('.board-grid').innerHTML()).not.toMatch(/cyan|magenta|data-face|face-id/);
  await page.getByLabel('Grid size').focus();
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: 'New Game', exact: true })).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: 'Restart', exact: true })).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(card(page, 0)).toBeFocused();
  await page.keyboard.press('ArrowLeft');
  await page.keyboard.press('ArrowUp');
  await expect(card(page, 0)).toBeFocused();
  await page.keyboard.press('Control+ArrowRight');
  await page.keyboard.press('Shift+Enter');
  await page.keyboard.press('Control+Space');
  await expect(card(page, 0)).toHaveAccessibleName('Row 1, column 1, closed');
  await page.keyboard.press('Enter');
  await expect(card(page, 0)).toHaveAccessibleName('Row 1, column 1, cyan solid plus, marker top, revealed');
  await capture('First reveal, face and state available');
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('Space');
  await page.clock.runFor(800);
  await page.keyboard.press('ArrowLeft');
  await page.keyboard.press('Enter');
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('Enter');
  await page.clock.runFor(800);
  expect(announcements.filter((text) => text === 'No match. Cards close after a short pause.')).toHaveLength(2);
  let position = 1;
  const move = async (target: number) => {
    while (Math.floor(position / 4) < Math.floor(target / 4)) { await page.keyboard.press('ArrowDown'); position += 4; }
    while (Math.floor(position / 4) > Math.floor(target / 4)) { await page.keyboard.press('ArrowUp'); position -= 4; }
    while (position % 4 < target % 4) { await page.keyboard.press('ArrowRight'); position += 1; }
    while (position % 4 > target % 4) { await page.keyboard.press('ArrowLeft'); position -= 1; }
  };
  for (let face = 0; face < 8; face += 1) {
    for (const index of DECK.flatMap((value, index) => value === face ? [index] : [])) {
      await move(index);
      await page.keyboard.press('Enter');
    }
    await page.clock.runFor(200);
    if (face === 0) await capture('First pair, matched cards remain focusable');
  }
  await expect(page.getByText('All pairs found!', { exact: true })).toBeVisible();
  expect(announcements.filter((text) => text.startsWith('Pair found.'))).toHaveLength(8);
  expect(announcements.filter((text) => text.includes('All pairs found in 10 moves and'))).toHaveLength(1);
  await capture('Completed board, final turn and win in one announcement');
  await page.keyboard.press('Tab');
  await expect(page.locator('summary')).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(card(page, position)).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(page.getByRole('button', { name: 'Restart', exact: true })).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Enter');
  await expect(page.getByRole('button', { name: 'New Game', exact: true })).toBeFocused();
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  await expect(card(page, 0)).toBeFocused();
  await capture('New deal, native Tab exit and reset tab stop');
  evidence.push(`\nAnnouncements, in order:\n${announcements.join('\n')}`);
  const text = evidence.join('\n');
  await mkdir('evidence', { recursive: true });
  await writeFile('evidence/keyboard-journey.txt', text);
  await info.attach('accessibility-tree', { body: text, contentType: 'text/plain' });
});
EOF
cat > tests/e2e/layout.spec.ts <<'EOF'
import { mkdir } from 'node:fs/promises';
import { expect, test } from '@playwright/test';
import { generateDeck } from '../../src/game/boardCode.ts';
import { card, loadBoard, loadSnapshot } from './helpers.ts';

const viewports = [{ width: 360, height: 800 }, { width: 1280, height: 800 }, { width: 640, height: 400 }];
for (const viewport of viewports) {
  for (const size of [4, 16]) {
    test(`${size}x${size} fits and scrolls at ${viewport.width}x${viewport.height}`, async ({ browser }) => {
      const context = await browser.newContext({ viewport, deviceScaleFactor: viewport.width === 640 ? 2 : 1, hasTouch: true });
      const page = await context.newPage();
      await page.goto('/');
      await loadBoard(page, `np1-${size}-1`);
      await expect(page.locator('.card')).toHaveCount(size * size);
      expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
      const geometry = await card(page, 0).evaluate((element) => {
        const bounds = element.getBoundingClientRect();
        const css = getComputedStyle(element);
        return { width: bounds.width, height: bounds.height, border: css.borderWidth, radius: css.borderRadius };
      });
      expect(geometry.width).toBeGreaterThanOrEqual(44);
      expect(geometry.width).toBeLessThanOrEqual(88);
      expect(geometry.height).toBeCloseTo(geometry.width, 1);
      expect(geometry.border).toBe('2px');
      expect(geometry.radius).toBe('8px');
      await card(page, 0).focus();
      for (let step = 1; step < size; step += 1) await page.keyboard.press('ArrowDown');
      for (let step = 1; step < size; step += 1) await page.keyboard.press('ArrowRight');
      await expect(card(page, size * size - 1)).toBeFocused();
      const visible = await card(page, size * size - 1).evaluate((element) => {
        const parent = element.closest('.board-scroll');
        if (!parent) throw new Error('Missing scroll area');
        const card = element.getBoundingClientRect();
        const area = parent.getBoundingClientRect();
        return card.left - 5 >= area.left && card.top - 5 >= area.top &&
          card.right + 5 <= area.right && card.bottom + 5 <= area.bottom;
      });
      expect(visible).toBe(true);
      await page.keyboard.press('Enter');
      await expect(card(page, size * size - 1)).toHaveAccessibleName(/revealed$/);
      await page.getByRole('button', { name: 'Restart', exact: true }).click();
      await card(page, size * size - 1).tap();
      await expect(card(page, size * size - 1)).toHaveAccessibleName(/revealed$/);
      expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
      if (viewport.width === 360 && size === 4) {
        await mkdir('evidence', { recursive: true });
        await page.screenshot({ path: 'evidence/phone.png', fullPage: true });
      }
      await context.close();
    });
  }
}
test('all 128 faces at 44px, grayscale and reduced motion', async ({ page, browser }, info) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto('/');
  const deck = generateDeck(16, 1);
  await loadSnapshot(page, { version: 1, boardCode: 'np1-16-1', matched: deck.map((_, index) => index),
    selection: { kind: 'closed' }, moves: 128, elapsedMs: 5000, started: true });
  await expect(page.locator('.card svg')).toHaveCount(256);
  expect(await card(page, 0).evaluate((element) => getComputedStyle(element).transitionDuration)).toBe('0s');
  expect(await page.locator('.win-banner').evaluate((element) => getComputedStyle(element).animationName)).toBe('none');
  const faces: string[] = [];
  for (let id = 0; id < 128; id += 1) {
    faces.push(`<div><div class="card">${await card(page, deck.indexOf(id)).innerHTML()}</div><span>${id}</span></div>`);
  }
  const sheet = await browser.newPage({ viewport: { width: 832, height: 640 } });
  await sheet.setContent(`<style>*{box-sizing:border-box}body{margin:0;padding:16px;background:#090B14;color:white;font:14px/24px sans-serif}
    main{display:grid;grid-template-columns:repeat(16,44px);gap:6px;filter:grayscale(1)}.card{width:44px;height:44px;
    border:2px solid #8BEA7D;border-radius:8px;background:#111625}.card svg{width:100%;height:100%}.match-check{display:none}</style>
    <main>${faces.join('')}</main>`);
  await mkdir('evidence', { recursive: true });
  await sheet.locator('main').screenshot({ path: 'evidence/faces-grayscale.png' });
  await info.attach('128 grayscale identities at 44px', { path: 'evidence/faces-grayscale.png', contentType: 'image/png' });
  await sheet.close();
});
EOF
cat > tests/e2e/delivery.spec.ts <<'EOF'
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { expect, test } from '@playwright/test';
import { card, exportState, finish, loadBoard, loadSnapshot, nearWin } from './helpers.ts';

test('the single HTML plays directly from disk with networking blocked', async ({ browser }) => {
  const context = await browser.newContext({ offline: true });
  const page = await context.newPage();
  const requests: string[] = [];
  const errors: string[] = [];
  page.on('request', (request) => requests.push(request.url()));
  page.on('pageerror', (error) => errors.push(error.message));
  await page.goto(pathToFileURL(resolve('dist/index.html')).href);
  await expect(page.getByRole('heading', { name: 'Neon Pairs' })).toBeVisible();
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await loadBoard(page, 'np1-4-42');
  await finish(page, 4);
  expect((await exportState(page)).moves).toBe(8);
  expect(requests.filter((url) => !url.startsWith('file:'))).toEqual([]);
  expect(errors).toEqual([]);
  await context.close();
});
test('served preferences persist size and best but never active progress or unrelated keys', async ({ page }) => {
  await page.goto('/');
  await page.evaluate(() => localStorage.setItem('unrelated', 'keep'));
  await page.getByLabel('Grid size').selectOption('6');
  await card(page, 0).click();
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await expect(card(page, 0)).toHaveAccessibleName(/closed$/);
  await loadBoard(page, 'np1-8-1');
  await loadBoard(page, 'np1-5-1');
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('8');
  expect(await page.evaluate(() => localStorage.getItem('unrelated'))).toBe('keep');
});
test('storage failures leave play, imports, completion and in-memory best available', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', { configurable: true,
      get() { throw new Error('Storage denied'); } });
  });
  await page.goto('/');
  await loadSnapshot(page, nearWin());
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await card(page, 0).click();
  await card(page, 11).click();
  await expect(page.getByText('Best: 8', { exact: true })).toBeVisible();
  await page.getByRole('button', { name: 'New Game', exact: true }).click();
  await expect(page.getByText('Best: 8', { exact: true })).toBeVisible();
  await card(page, 0).click();
  await expect(card(page, 0)).toHaveAccessibleName(/revealed$/);
});
test('hover, cancellation and the normal context menu do not reveal cards; touch uses the same action', async ({ browser }) => {
  const context = await browser.newContext({ hasTouch: true });
  const page = await context.newPage();
  await page.goto('/');
  await loadBoard(page);
  await card(page, 0).hover();
  await card(page, 0).dispatchEvent('pointercancel', { pointerType: 'touch' });
  await card(page, 0).click({ button: 'right' });
  await expect(card(page, 0)).toHaveAccessibleName(/closed$/);
  await page.keyboard.press('Escape');
  await card(page, 0).tap();
  await card(page, 11).tap();
  await expect(card(page, 0)).toHaveAttribute('aria-disabled', 'true');
  await expect(page.getByText('Moves: 1', { exact: true })).toBeVisible();
  await context.close();
});
EOF

